\set ON_ERROR_STOP on
DO $test$ DECLARE k text; r jsonb; BEGIN
SELECT legacy_idempotency_key INTO k FROM public.pos_financial_operations WHERE idempotency_key='lab-race-24-normal';
r:=public.pos_create_cloud_sale_cashier_inventory('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-race-24","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-race-24","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb->'sale','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-race-24","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-race-24","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb->'items','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-race-24","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-race-24","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb->'payments','lab-cash-a',k);
IF (r->>'success')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'LEGACY_RECEIPT_NOT_RECOVERED: %',r; END IF;
IF (SELECT stock FROM public.pos_products WHERE id='lab-race-24-product')<>18 OR (SELECT count(*) FROM public.pos_sales WHERE id LIKE 'lab-race-24%')<>1 OR (SELECT count(*) FROM public.pos_inventory_movements WHERE product_id='lab-race-24-product')<>1 THEN RAISE EXCEPTION 'LEGACY_REPLAY_EFFECTS'; END IF;
END $test$;